#[tarpc::service]
trait OrderFacade {                                  // the contract, in code
    async fn place_order(customer: String, lines: Vec<OrderLine>) -> OrderConfirmation;
}

impl OrderFacade for OrderServer {
    async fn place_order(self, _: context::Context, customer: String, lines: Vec<OrderLine>)
        -> OrderConfirmation {
        let order = domain::create_order(customer, lines);   // fine-grained model
        to_confirmation(order, price(&order))                // serde payload
    }
}
